@startuml

class SensorController {
  + inhabitants : list
  + apartment : Apartment
}

class Inhabitant {
  + username : string
  + password : string
  + emailAddress : string
  + isAdmin : boolean
}

class Sensor {
  + vendorId : string
  + description : string
  + unit : Unit
  + threshold : float
}

class TemperatureSensor extends Sensor {
  + minValue : float
  + maxValue : float
}

class PowerSensor extends Sensor {
  + counterReading : float
}

enum Unit {
  CELSIUS
  WATT
}

class Room {
  + description : string
}

class Apartment {
  + address : string
}

class MeasuredValue {
  + timestamp : datetime
  + value : float
}

class EMonitor {}

SensorController "1" o-- "*" Sensor
SensorController "1" o-- "*" Inhabitant
SensorController "1" o-- "1" Apartment
Apartment "1" *-- "2..*" Room
Room "1" *-- "*" Sensor
Inhabitant "1" --> "*" Sensor : query
Inhabitant "1" --> "*" Sensor : configure
Sensor "1" -- "*" MeasuredValue
Sensor "1" --> "1" MeasuredValue : lastValue
EMonitor ..> SensorController : checks
EMonitor ..> Sensor : checks thresholds

@enduml

